def countBestPlans(nums):
    M = 1000000007
    b2, c2 = 0, 1      # prefix of length i-2
    b1, c1 = 0, 1      # prefix of length i-1
    for x in nums:
        tb, tc = b2 + x, c2
        if tb > b1:
            nb, nc = tb, tc
        elif tb < b1:
            nb, nc = b1, c1
        else:
            nb, nc = b1, (c1 + tc) % M
        b2, c2, b1, c1 = b1, c1, nb, nc
    return c1 % M
